/* Deep: the thumb breathes, as if it is working harder. */
.effort.lvl-high input[type='range']::-webkit-slider-thumb { animation: effort-glow 1.8s ease-in-out infinite; }
.effort.lvl-high input[type='range']::-moz-range-thumb { animation: effort-glow 1.8s ease-in-out infinite; }
@keyframes effort-glow {
  50% { box-shadow: 0 0 0 7px color-mix(in srgb, var(--red) 28%, transparent), 0 0 18px color-mix(in srgb, var(--red) 55%, transparent); }
}
.effort-stops {
  display: flex;
  justify-content: space-between;
  margin-top: 6px;
}
.effort-stops button {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  width: 33%;
  padding: 0;
  border: 0;
  background: none;
  color: var(--muted);
  cursor: pointer;
  font: inherit;
  transition: color 0.2s;
}
.effort-stops button:first-child { align-items: flex-start; }
.effort-stops button:last-child { align-items: flex-end; }
.effort-stops button b { font-size: 13.5px; font-weight: 500; }
.effort-stops button small { font-size: 11.5px; opacity: 0.75; }
.effort-stops button.on { color: var(--text); }
.effort-stops button.on b { font-weight: 600; }
.effort-stops button:hover:not(:disabled) { color: var(--text); }
.effort-hint { flex: 1 1 260px; max-width: 560px; }
